window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-88fa47157dbc435d"]={"versions": [{"id": "FIG-88fa47157dbc435d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Erläuterungsbox bzw. Hinweistext innerhalb der AUTOSAR-Spezifikation für den OCU-Treiber (Output Compare Unit Driver, Classic Platform MCAL). Das Diagramm stellt das zeitliche Zusammenspiel beim Setzen eines Vergleichswerts (Compare Threshold) vor dem Eintreten des Ziel-Vergleichsereignisses (Compare Match) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OCU Driver (Treiber)</strong>: Verwaltende MCAL-Softwarekomponente, die für das Konfigurieren des Schwellenwerts, die Interrupt-Auslösung und den Aufruf der Benachrichtigungsfunktion zuständig ist.\n</li><li><strong>Threshold (Vergleichsschwelle)</strong>: Der in das Hardware-Register geschriebene Zielwert.\n</li><li><strong>Interrupt / Notification function</strong>: Schnittstellen und Callback-Mechanismen zur Benachrichtigung übergeordneter Schichten bei Wertegleichheit.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Schwellenwert (Threshold) wird in den OCU-Kanal geschrieben.\n</li><li>Der Zähler erreicht den gesetzten Schwellenwert erst nach dem Schreibvorgang (Gleichheit tritt nach dem Schreiben ein).\n</li><li>Bei Erreichen der Gleichheit (Equality / Compare Match) löst der OCU-Treiber einen Interrupt aus.\n</li><li>Der OCU-Treiber ruft daraufhin die konfigurierte Benachrichtigungsfunktion (Notification Function) auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Beschreibt die normative Anforderung an das reguläre Verhalten des OCU-Treibers: Wenn ein Schwellenwert rechtzeitig vor dem Compare Match geschrieben wird, muss der Hardware-Interrupt zuverlässig ausgelöst und der zugeordnete Benachrichtigungs-Callback ausgeführt werden.</p>"}, {"id": "FIG-724e847eceb86d19", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Erläuterungsbox bzw. Hinweistext innerhalb der AUTOSAR-Spezifikation für den OCU-Treiber (Output Compare Unit Driver, Classic Platform MCAL). Das Diagramm stellt das zeitliche Zusammenspiel beim Setzen eines Vergleichswerts (Compare Threshold) vor dem Eintreten des Ziel-Vergleichsereignisses (Compare Match) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OCU Driver (Treiber)</strong>: Verwaltende MCAL-Softwarekomponente, die für das Konfigurieren des Schwellenwerts, die Interrupt-Auslösung und den Aufruf der Benachrichtigungsfunktion zuständig ist.\n</li><li><strong>Threshold (Vergleichsschwelle)</strong>: Der in das Hardware-Register geschriebene Zielwert.\n</li><li><strong>Interrupt / Notification function</strong>: Schnittstellen und Callback-Mechanismen zur Benachrichtigung übergeordneter Schichten bei Wertegleichheit.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Schwellenwert (Threshold) wird in den OCU-Kanal geschrieben.\n</li><li>Der Zähler erreicht den gesetzten Schwellenwert erst nach dem Schreibvorgang (Gleichheit tritt nach dem Schreiben ein).\n</li><li>Bei Erreichen der Gleichheit (Equality / Compare Match) löst der OCU-Treiber einen Interrupt aus.\n</li><li>Der OCU-Treiber ruft daraufhin die konfigurierte Benachrichtigungsfunktion (Notification Function) auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Beschreibt die normative Anforderung an das reguläre Verhalten des OCU-Treibers: Wenn ein Schwellenwert rechtzeitig vor dem Compare Match geschrieben wird, muss der Hardware-Interrupt zuverlässig ausgelöst und der zugeordnete Benachrichtigungs-Callback ausgeführt werden.</p>"}, {"id": "FIG-9d4833312714b4c6", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Erläuterungsbox bzw. Hinweistext innerhalb der AUTOSAR-Spezifikation für den OCU-Treiber (Output Compare Unit Driver, Classic Platform MCAL). Das Diagramm stellt das zeitliche Zusammenspiel beim Setzen eines Vergleichswerts (Compare Threshold) vor dem Eintreten des Ziel-Vergleichsereignisses (Compare Match) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OCU Driver (Treiber)</strong>: Verwaltende MCAL-Softwarekomponente, die für das Konfigurieren des Schwellenwerts, die Interrupt-Auslösung und den Aufruf der Benachrichtigungsfunktion zuständig ist.\n</li><li><strong>Threshold (Vergleichsschwelle)</strong>: Der in das Hardware-Register geschriebene Zielwert.\n</li><li><strong>Interrupt / Notification function</strong>: Schnittstellen und Callback-Mechanismen zur Benachrichtigung übergeordneter Schichten bei Wertegleichheit.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Schwellenwert (Threshold) wird in den OCU-Kanal geschrieben.\n</li><li>Der Zähler erreicht den gesetzten Schwellenwert erst nach dem Schreibvorgang (Gleichheit tritt nach dem Schreiben ein).\n</li><li>Bei Erreichen der Gleichheit (Equality / Compare Match) löst der OCU-Treiber einen Interrupt aus.\n</li><li>Der OCU-Treiber ruft daraufhin die konfigurierte Benachrichtigungsfunktion (Notification Function) auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Beschreibt die normative Anforderung an das reguläre Verhalten des OCU-Treibers: Wenn ein Schwellenwert rechtzeitig vor dem Compare Match geschrieben wird, muss der Hardware-Interrupt zuverlässig ausgelöst und der zugeordnete Benachrichtigungs-Callback ausgeführt werden.</p>"}, {"id": "FIG-b32652261a5c1e47", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Erläuterungsbox bzw. Hinweistext innerhalb der AUTOSAR-Spezifikation für den OCU-Treiber (Output Compare Unit Driver, Classic Platform MCAL). Das Diagramm stellt das zeitliche Zusammenspiel beim Setzen eines Vergleichswerts (Compare Threshold) vor dem Eintreten des Ziel-Vergleichsereignisses (Compare Match) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OCU Driver (Treiber)</strong>: Verwaltende MCAL-Softwarekomponente, die für das Konfigurieren des Schwellenwerts, die Interrupt-Auslösung und den Aufruf der Benachrichtigungsfunktion zuständig ist.\n</li><li><strong>Threshold (Vergleichsschwelle)</strong>: Der in das Hardware-Register geschriebene Zielwert.\n</li><li><strong>Interrupt / Notification function</strong>: Schnittstellen und Callback-Mechanismen zur Benachrichtigung übergeordneter Schichten bei Wertegleichheit.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Schwellenwert (Threshold) wird in den OCU-Kanal geschrieben.\n</li><li>Der Zähler erreicht den gesetzten Schwellenwert erst nach dem Schreibvorgang (Gleichheit tritt nach dem Schreiben ein).\n</li><li>Bei Erreichen der Gleichheit (Equality / Compare Match) löst der OCU-Treiber einen Interrupt aus.\n</li><li>Der OCU-Treiber ruft daraufhin die konfigurierte Benachrichtigungsfunktion (Notification Function) auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Beschreibt die normative Anforderung an das reguläre Verhalten des OCU-Treibers: Wenn ein Schwellenwert rechtzeitig vor dem Compare Match geschrieben wird, muss der Hardware-Interrupt zuverlässig ausgelöst und der zugeordnete Benachrichtigungs-Callback ausgeführt werden.</p>"}, {"id": "FIG-0deba07ac5797040", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Erläuterungsbox bzw. Hinweistext innerhalb der AUTOSAR-Spezifikation für den OCU-Treiber (Output Compare Unit Driver, Classic Platform MCAL). Das Diagramm stellt das zeitliche Zusammenspiel beim Setzen eines Vergleichswerts (Compare Threshold) vor dem Eintreten des Ziel-Vergleichsereignisses (Compare Match) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>OCU Driver (Treiber)</strong>: Verwaltende MCAL-Softwarekomponente, die für das Konfigurieren des Schwellenwerts, die Interrupt-Auslösung und den Aufruf der Benachrichtigungsfunktion zuständig ist.\n</li><li><strong>Threshold (Vergleichsschwelle)</strong>: Der in das Hardware-Register geschriebene Zielwert.\n</li><li><strong>Interrupt / Notification function</strong>: Schnittstellen und Callback-Mechanismen zur Benachrichtigung übergeordneter Schichten bei Wertegleichheit.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein Schwellenwert (Threshold) wird in den OCU-Kanal geschrieben.\n</li><li>Der Zähler erreicht den gesetzten Schwellenwert erst nach dem Schreibvorgang (Gleichheit tritt nach dem Schreiben ein).\n</li><li>Bei Erreichen der Gleichheit (Equality / Compare Match) löst der OCU-Treiber einen Interrupt aus.\n</li><li>Der OCU-Treiber ruft daraufhin die konfigurierte Benachrichtigungsfunktion (Notification Function) auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Beschreibt die normative Anforderung an das reguläre Verhalten des OCU-Treibers: Wenn ein Schwellenwert rechtzeitig vor dem Compare Match geschrieben wird, muss der Hardware-Interrupt zuverlässig ausgelöst und der zugeordnete Benachrichtigungs-Callback ausgeführt werden.</p>"}, {"id": "FIG-b754826f041c9abb", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Registerzustandsdiagramm für den AUTOSAR Classic OCU-Treiber (Output Compare Unit Driver, MCAL). Es illustriert die zeitliche Beziehung zwischen Zählerstand, Referenzwert, Schreibzeitpunkt und dem Compare-Match-Ereignis bei einem frei laufenden Zähler (Free running counter).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Free running counter</strong>: Fortlaufend inkrementierender Hardware-Zähler mit dargestellten Ticks/Werten von 29 bis 39 …\n</li><li><strong>Reference Value</strong>: Referenzwert (im Beispiel Wert 30, grün hervorgehoben).\n</li><li><strong>Current value of the counter when the threshold is actually written</strong>: Konkreter Zählerstand zum Zeitpunkt des tatsächlichen Schreibvorgangs des Schwellenwerts (im Beispiel Zählerstand 32, markiert mit blauem Hinweiskasten und Pfeil).\n</li><li><strong>Compare threshold (Absolute value)</strong>: Zu vergleichender absoluter Schwellenwert (im Beispiel Wert 35, rötlich umrandet, mit Zuordnungspfeil auf Zählerzelle 35).\n</li><li><strong>OCU Driver / Interrupt &amp; Notification function</strong>: Treiberinstanz zur Erkennung der Gleichheit, Auslösung des Hardware-Interrupts (symbolisiert durch den nach unten gerichteten Blockpfeil bei Zählerstand 35) und Ausführung des Benachrichtigungs-Callbacks.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der frei laufende Zähler inkrementiert ab dem Referenzwert (Wert 30).\n</li><li>Zu einem späteren Zählerstand (im Beispiel Zählerstand 32) wird der absolute Schwellenwert (Wert 35) in das Compare-Register geschrieben.\n</li><li>Da der Schwellenwert (35) größer ist als der Zählerstand beim Schreiben (32), liegt der Ziel-Vergleichswert in der Zukunft des Zählers.\n</li><li>Der Zähler inkrementiert weiter über 33 und 34 bis zum Stand 35.\n</li><li>Bei Erreichen der Gleichheit (Stand 35 = Compare Threshold) wird das Compare-Match-Ereignis ausgelöst (nach unten weisender Ereignispfeil).\n</li><li>Der Interrupt wird getriggert und der Treiber ruft die Benachrichtigungsfunktion auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Beschreibt die normative Anforderung an das reguläre Verhalten des OCU-Treibers: Wenn ein Schwellenwert rechtzeitig vor dem Compare Match geschrieben wird, muss der Hardware-Interrupt zuverlässig ausgelöst und der zugeordnete Benachrichtigungs-Callback ausgeführt werden.</p>"}], "trans": [{"from": "FIG-88fa47157dbc435d", "to": "FIG-724e847eceb86d19", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-724e847eceb86d19", "to": "FIG-9d4833312714b4c6", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9d4833312714b4c6", "to": "FIG-b32652261a5c1e47", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b32652261a5c1e47", "to": "FIG-0deba07ac5797040", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0deba07ac5797040", "to": "FIG-b754826f041c9abb", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Ergänzung der zuvor fehlenden grafischen Darstellung eines frei laufenden Zählers (Werte 29 bis 39 …).\n</li><li>Ergänzung der Visualisierung für „Reference Value“ (Wert 30, grün umrandet).\n</li><li>Ergänzung der Visualisierung für den aktuellen Zählerstand beim Schreiben („Current value of the counter when the threshold is actually written“, Pfeil auf Wert 32).\n</li><li>Ergänzung der Visualisierung für „Compare threshold (Absolute value)“ (Wert 35, rötlich umrandet) mit Zuordnungspfeil auf Zählerstand 35 und Signal-/Ereignispfeil.\n</li></ul>"}]};
